def material_symbol_char(content: str, fill: bool = False) -> str:
    """Return the single cmap character for a Material Symbol name.
    That character can be used to access a symbol in
    ``material_symbols_outlined_pua_cmap.woff2``
    """
    codepoints = MATERIAL_SYMBOL_CODEPOINTS_FILL_0
    if fill:
        codepoints = MATERIAL_SYMBOL_CODEPOINTS_FILL_1
    return chr(codepoints[content])
